import{_ as r,o as a,c as t,a5 as o}from"./chunks/framework.CslsFoWx.js";const h=JSON.parse('{"title":"Synchronisation : horloge décalée, rétention locale, caisse révoquée (09/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-09-synchro-horloge-retention.md","filePath":"generated/preuves/2026-11-09-synchro-horloge-retention.md","lastUpdated":null}'),n={name:"preuves/2026-11-09-synchro-horloge-retention.md"};function s(i,e,l,c,d,u){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="synchronisation-horloge-decalee-retention-locale-caisse-revoquee-09-11-2026" tabindex="-1">Synchronisation : horloge décalée, rétention locale, caisse révoquée (09/11/2026) <a class="header-anchor" href="#synchronisation-horloge-decalee-retention-locale-caisse-revoquee-09-11-2026" aria-label="Permalink to &quot;Synchronisation : horloge décalée, rétention locale, caisse révoquée (09/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-09-synchro-horloge-retention</code> · 0 image(s) · 0 trace(s)</p><div><p>Carte Trello « P3 · Synchronisation : horloge décalée, rétention locale, retour à l&#39;appairage d&#39;une caisse révoquée ». Spec 10 RG-SYNC-07 / 20 / 21 et §4.1 ; spec 01 RG-AUTH-14/26 ; spec 04 RG-CASH-28.</p><p><strong>Captures non faites (09/11 au soir)</strong> : le Mac a atteint la limite de processus par utilisateur (2 624 / 2 666, dont ~1 260 processus zombies des deux émulateurs Android de l&#39;utilisateur) — <code>fork failed</code> partout, un simulateur de plus était impossible à démarrer. Le simulateur dédié « Horloge-iPad » avait été appairé à la vraie pile (serveur du worktree sur 8094, base <code>pos_horloge</code>, « Épicerie Lumière (démo) ») avant la panne ; tout a été arrêté ensuite. Le comportement est prouvé par les tests (shared, Android, iOS, serveur). Les pages d&#39;aide n&#39;ont pas encore les images (texte seul) : à ajouter dans <code>help/public/captures/depannage/caisse-ne-synchronise-plus/</code>.</p><h2 id="ios-a-capturer-quand-la-machine-le-permet" tabindex="-1">iOS (à capturer quand la machine le permet) <a class="header-anchor" href="#ios-a-capturer-quand-la-machine-le-permet" aria-label="Permalink to &quot;iOS (à capturer quand la machine le permet)&quot;">​</a></h2><p>Montage sans réglage de dev dans le produit : un proxy de test (<code>scratchpad/horloge/proxy-horloge.py 8095 http://localhost:8094 720000</code>) relaie le serveur et décale l&#39;en-tête <code>X-Server-Time</code> de +12 min ; l&#39;app pointe sur <code>http://localhost:8095</code> (<code>defaults write tn.pos.app server.url …</code>). iPad en paysage, Nora (caisse) connectée.</p><table tabindex="0"><thead><tr><th>Fichier attendu</th><th>Scène</th></tr></thead><tbody><tr><td><code>02-heure-incorrecte.webp</code></td><td>Écran de vente : bandeau « Heure de l&#39;appareil incorrecte : en retard de 12 min sur le serveur… La vente continue. » et pastille ⚠ « Attention ».</td></tr><tr><td><code>03-synchro-critique.webp</code></td><td><code>sync_state.last_pull_at</code> reculé de 22 jours dans <code>pos.db</code> du simulateur, proxy arrêté (serveur injoignable), toucher la pastille : feuille Synchronisation avec « Attention » et « Synchronisation critique : 22 jours sans synchronisation… ».</td></tr><tr><td><code>04-caisse-revoquee.webp</code></td><td>Proxy relancé, caisse révoquée par <code>POST /devices/{id}/revoke</code> (ou Réglages › Appareils), « Synchroniser maintenant » : écran plein « Caisse révoquée », puis « Revenir à l&#39;appairage » → écran d&#39;appairage.</td></tr></tbody></table><h2 id="android-a-capturer-par-l-integrateur-sur-emulator-5554" tabindex="-1">Android (à capturer par l&#39;intégrateur sur emulator-5554) <a class="header-anchor" href="#android-a-capturer-par-l-integrateur-sur-emulator-5554" aria-label="Permalink to &quot;Android (à capturer par l&#39;intégrateur sur emulator-5554)&quot;">​</a></h2><p>Pas d&#39;émulateur supplémentaire (mémoire). Scène exacte, tablette en paysage, caisse appairée sur le serveur qui porte ces commits :</p><ol><li><strong>Heure incorrecte</strong> : réglages de l&#39;émulateur › Date et heure › désactiver « Réglage automatique » et avancer l&#39;heure de 12 min ; revenir à l&#39;app, toucher « Synchroniser maintenant » (ou attendre le pull de 20 s) → bandeau orange « Heure de l&#39;appareil incorrecte : en avance de 12 min sur le serveur… » (<code>testTag</code> <code>bandeau-synchro-attention</code>) et pastille ⚠ « Attention » ; toucher la pastille → feuille « Synchronisation » avec la pastille « Attention » et l&#39;avertissement (<code>synchro-attention</code>). Remettre l&#39;heure automatique ensuite.</li><li><strong>Seuil critique</strong> : <code>adb shell run-as tn.pos.app sqlite3 databases/pos.db &quot;UPDATE sync_state SET last_pull_at = (strftime(&#39;%s&#39;,&#39;now&#39;) - 22*86400)*1000&quot;</code> (ou couper le serveur 21 jours…), couper le réseau de l&#39;émulateur, relancer l&#39;app → bandeau rouge « Synchronisation critique : 22 jours sans synchronisation… » ; à la connexion d&#39;un responsable, notification « Caisse non synchronisée ».</li><li><strong>Caisse révoquée</strong> : révoquer la caisse au back-office (Réglages › Appareils › Révoquer), puis « Synchroniser maintenant » → écran plein « Caisse révoquée » (<code>ecran-caisse-revoquee</code>) ; « Revenir à l&#39;appairage » → écran d&#39;appairage.</li></ol></div>',3)])])}const m=r(n,[["render",s]]);export{h as __pageData,m as default};
